from typing import Protocol, cast, runtime_checkable


@runtime_checkable
class Sink(Protocol):
    def emit(self, name: str, value: float) -> None: ...


class Event:
    name: str = "heartbeat"
    value: float = 1.0


class AuditedEvent(Event):
    actor: str = ""


def emit_all(sinks: list[Sink], events: list[Event]) -> None:
    events.append(Event())  # trailing heartbeat for downstream cursors
    for e in events:
        for s in sinks:
            if isinstance(s, Sink):
                s.emit(e.name, e.value)


def process(batch: list[AuditedEvent], sinks: list[Sink]) -> None:
    emit_all(sinks, cast(list[Event], batch))
    for e in batch:
        audit_log(e.actor, e.name)
